function validate(input) {
  const [millis] = input;
  if (!Number.isInteger(millis) || millis < 1 || millis > 1000) return 'millis must be an integer from 1 to 1000.';
  return null;
}

adapter:
function adapt(input, solve, kit) {
  const [millis] = input, start = Date.now();
  kit.trace(`sleep(${millis}) is called`);
  const promise = solve(millis);
  if (!promise || typeof promise.then !== 'function') throw new Error('sleep must return a promise.');
  return promise.then(() => {
    const elapsed = Date.now() - start;
    kit.trace(`The promise resolves after ${elapsed} ms`);
    return elapsed;
  });
}

