function sleep(millis) {
  return new Promise((resolve) => {
    let elapsed = 0;
    const ticker = setInterval(() => {
      elapsed += 1;
      if (elapsed === millis) {
        clearInterval(ticker);
        resolve();
      }
    }, 1);
  });
}

